import java.util.List;
import java.util.Iterator;

/**
 * Abstract class Creature - A class representing shared characteristics of creatures(animals and plants.)
 *
 * @version 2022/03/02
 */
public abstract class Creature
{
    // Whether the creature is alive or not.
    private boolean alive;
    // The creature's field.
    private Field field;
    // The creature's position in the field.
    private Location location;


    /**
     * Create a new creature at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Creature(Field field, Location location)
    {
        alive = true;
        this.field = field;
        setLocation(location);
    }

    /**
     * Make this creature act - that is: make it do
     * whatever it wants/needs to do.
     * @param newCreatures A list to receive newly born creatures.
     * @param atDayTime true if current step is daytime false otherwise.
     * @param oxygenLevel The inital level of dissolved oxygen in the water.
     * @param disease The disease may happened during simulation.  
     * @param step current step.
     * 
     * @return the oxygen level the species produced or consumed after action.
     */
    abstract public double act(List<Creature> newCreatures, boolean atDayTime, double oxygenLevel, Disease disease, int step);

    /**
     * Check whether the creature is alive or not.
     * @return true if the creature is still alive.
     */
    protected boolean isAlive()
    {
        return alive;
    }

      /**
     * Indicate that the creature is no longer alive.
     * It is removed from the field.
     */
    protected void setDead()
    {
        alive = false;
        if(location != null) {
            field.clear(location);
            location = null;
            field = null;
        }
    }

    /**
     * Return the creature's location.
     * @return The creature's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Place the creature at the new location in the given field.
     * @param newLocation The creature's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }

     /**
     * Return the creature's field.
     * @return The creature's field.
     */
    protected Field getField()
    {
        return field;
    }


}

import java.util.Collections;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Random;
import java.util.ArrayList;

/**
 * Represent a rectangular grid of field positions.
 * Each position is able to store a single creature.
 *
 * @version 2022/03/02
 */
public class Field
{
    // A random number generator for providing random locations.
    private static final Random rand = Randomizer.getRandom();

    // The depth and width of the field.
    private int depth, width;
    // Storage for the creatures.
    private Object[][] field;

    /**
     * Represent a field of the given dimensions.
     * @param depth The depth of the field.
     * @param width The width of the field.
     */
    public Field(int depth, int width)
    {
        this.depth = depth;
        this.width = width;
        field = new Object[depth][width];
    }

    /**
     * Empty the field.
     */
    public void clear()
    {
        for(int row = 0; row < depth; row++) {
            for(int col = 0; col < width; col++) {
                field[row][col] = null;
            }
        }
    }

    /**
     * Clear the given location.
     * @param location The location to clear.
     */
    public void clear(Location location)
    {
        field[location.getRow()][location.getCol()] = null;
    }

    /**
     * Place a creature at the given location.
     * If there is already a creature at the location it will
     * be lost.
     * @param creature The creature to be placed.
     * @param row Row coordinate of the location.
     * @param col Column coordinate of the location.
     */
    public void place(Object creature, int row, int col)
    {
        place(creature, new Location(row, col));
    }

    /**
     * Place an creature at the given location.
     * If there is already an creature at the location it will
     * be lost.
     * @param creature The creature to be placed.
     * @param location Where to place the creature.
     */
    public void place(Object creature, Location location)
    {
        field[location.getRow()][location.getCol()] = creature;
    }

    /**
     * Return the creature at the given location, if any.
     * @param location Where in the field.
     * @return The creature at the given location, or null if there is none.
     */
    public Object getObjectAt(Location location)
    {
        return getObjectAt(location.getRow(), location.getCol());
    }

    /**
     * Return the creature at the given location, if any.
     * @param row The desired row.
     * @param col The desired column.
     * @return The creature at the given location, or null if there is none.
     */
    public Object getObjectAt(int row, int col)
    {
        return field[row][col];
    }

    /**
     * Generate a random location that is adjacent to the
     * given location, or is the same location.
     * The returned location will be within the valid bounds
     * of the field.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location randomAdjacentLocation(Location location)
    {
        List<Location> adjacent = adjacentLocations(location, 1);
        return adjacent.get(0);
    }

    /**
     * Get a shuffled list of the free adjacent locations.
     * @param location Get locations adjacent to this.
     * @return A list of free adjacent locations.
     */
    public List<Location> getFreeAdjacentLocations(Location location)
    {
        List<Location> free = new LinkedList<>();
        List<Location> adjacent = adjacentLocations(location, 1);
        for(Location next : adjacent) {
            if(getObjectAt(next) == null) {
                free.add(next);
            }
        }
        return free;
    }

    /**
     * Try to find a free location that is adjacent to the
     * given location. If there is none, return null.
     * The returned location will be within the valid bounds
     * of the field.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location freeAdjacentLocation(Location location)
    {
        // The available free ones.
         List<Location> free = getFreeAdjacentLocations(location);
        if(free.size() > 0) {
            return free.get(0);
        }
        else {
            return null;
        }
    }


    /**
     * Return a shuffled list of locations adjacent to the given one.
     * The list will INCLUDE the location itself.
     * All locations will lie within the grid.
     * 
     * @param location The location from which to generate adjacencies.
     * @return A list of locations adjacent to that given.
     */
    public List<Location> adjacentLocationsIncludingSelf(Location location, int adjacentDistance)
    {
        assert location != null : "Null location passed to adjacentLocations";
        // The list of locations to be returned.
        List<Location> locations = new LinkedList<>();
        if(location != null) {
            int row = location.getRow();
            int col = location.getCol();
            for(int roffset = -adjacentDistance; roffset <= adjacentDistance; roffset++) {
                int nextRow = row + roffset;
                if(nextRow >= 0 && nextRow < depth) {
                    for(int coffset = -adjacentDistance; coffset <= adjacentDistance; coffset++) {
                        int nextCol = col + coffset;
                        // Exclude invalid locations and the original location.
                        if(nextCol >= 0 && nextCol < width) {
                            locations.add(new Location(nextRow, nextCol));
                        }
                    }
                }
            }

            // Shuffle the list. Several other methods rely on the list
            // being in a random order.
            Collections.shuffle(locations, rand);
        }
        return locations;
    }

    /**
     * Return a shuffled list of locations adjacent to the given one.
     * The list will not include the location itself.
     * All locations will lie within the grid.
     * @param location The location from which to generate adjacencies.
     * @return A list of locations adjacent to that given.
     */
    public List<Location> adjacentLocations(Location location, int adjacentDistance)
    {
        assert location != null : "Null location passed to adjacentLocations";
        // The list of locations to be returned.
        List<Location> locations = new LinkedList<>();
        if(location != null) {
            int row = location.getRow();
            int col = location.getCol();
            for(int roffset = -adjacentDistance; roffset <= adjacentDistance; roffset++) {
                int nextRow = row + roffset;
                if(nextRow >= 0 && nextRow < depth) {
                    for(int coffset = -adjacentDistance; coffset <= adjacentDistance; coffset++) {
                        int nextCol = col + coffset;
                        // Exclude invalid locations and the original location.
                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
                            locations.add(new Location(nextRow, nextCol));
                        }
                    }
                }
            }

            // Shuffle the list. Several other methods rely on the list
            // being in a random order.
            Collections.shuffle(locations, rand);
        }
        return locations;
    }

    /**
     * Return the depth of the field.
     * @return The depth of the field.
     */
    public int getDepth()
    {
        return depth;
    }

    /**
     * Return the width of the field.
     * @return The width of the field.
     */
    public int getWidth()
    {
        return width;
    }
    /**
     * Generate a random location from the field.
     * Using randomWidth and randomDepth to create an instance of Location.
     * @return Location a random location.
     */
     public Location generateRandomLocation()
    {
       int randomWidth = rand.nextInt(width);
       int randomDepth = rand.nextInt(depth);

       return new Location(randomWidth, randomDepth);

    }
    /**
     * Create a list and holds all objects that is adjacent to this specific location.
     * @param location The location from which to generate adjacencies.
     * @param adjacentDistance used to Controls the range to which this method can search in the field.
     * @return a list of adjacent objects.

import java.util.List;
import java.lang.Math;

/**
 * A class representing shared characteristics of animals.
 *
 * @version 2022/03/02
 */
public abstract class Animal extends Creature
{   

    // sex of an animal, 0 = female and 1 = male
    private int sex;

    // The amount of oxygen an animal need to survive
    protected static final double ANIMAL_OXYGEN_REQUIRED = 0.0000009;
    // The possibility that an animal may be infected by a disease.
    protected static final double INFECTION_RATE = 1;
    // The possibility an animal may die of a disease.
    protected static final double MORTALITY_RATE = 1;
    // The steps an animal need to withstand in order to get immunity
    protected static final int stepStandNum = 3;

    // If the animal is infected by disease.
    private boolean isInfected;
    // If the animal is immuned from the diease.
    private boolean isImmuned;

    // Track the first step at which the animal is infected;
    protected int infectionStartStep;

    // total population that is die of disease.
    public static int populationDieOfDisease = 0;

    public Animal(Field field, Location location){
        super(field, location);
        sex = (int)(Math.round(Math.random()));
        isInfected = false;
        isImmuned = false;
        // Track the first step at which the animal is infected;
        infectionStartStep = 0;

    }

    /**
     * get the gender of an animal.
     * @return sex  0 = female and 1 = male.
     */
    public int getSex(){
        return sex;
    }

    /**
     * Every animal have different gender. and the implementation of this method is at its subclass.
     * 
     */
    public abstract boolean encounterWithDiffSex();

    public abstract Location search(Disease disease, int step);

    /**
     * identify whether a creature need to sleep
     * 
     * @param atDayTime true if it is at day time false if it is at night time.
     * @return true if currently it is night.
     */
    public boolean needSleep(boolean atDayTime){
        return !atDayTime;
    }


    /**
     * get whether an animal is infected.
     * 
     * @return true if an animal is infected, false otherwise. 
     */
    public boolean getIsInfected(){
        return isInfected;
    }

    /**
     * get if an animal is immuned.
     * 
     * @return true if an animal is immuned, false otherwise.
     */
    public boolean getIsImmuned(){
        return isImmuned;
    }

    /**
     * set an animal to be infected.
     * @param isInfected 
     */
    public void setIsInfected(boolean isInfected){
        this.isInfected = isInfected;
    }

    /**
     * set an animal to be immuned.
     * @param isImmuned 
     */
    public void setIsImmuned(boolean isImmuned){
        this.isImmuned = isImmuned;
    }

    /**
     *  Make an animal infected while the disease exists.
     *  
     *  @param disease disease 
     *  @param step current step.
     */
    protected void makeInfected(Disease disease, int step){
        if((!this.getIsImmuned()) && Randomizer.getRandom().nextDouble() <= disease.INFECTION_RATE)
            setIsInfected(true);  

        //if the animal is infected in current step, record its start step.
        if(getIsInfected() && infectionStartStep == 0)
            infectionStartStep = step;
    }

    /**
     * give the animal immunity while condition is met.
     * @param disease disease.
     * @param step int step.
     */
    protected void ifCanGrantImmunity(Disease disease, int step){
        // if an animal is infected, it may die. Otherwise assume it gets immuntity from that disease.
        if(getIsInfected() && !getIsImmuned()){
            if(step-infectionStartStep >= disease.NUMBER_OF_STEP_TO_WITHSTAND){
                setIsImmuned(true);
                setIsInfected(false);
            }  
        }
    }

    /**
     * set an animal to death if it is die of infection.
     * Return true if an animal dies of infection
     * 
     * @return true if an animal dies of infection.
     */ 

    protected boolean dieOfInfection(Disease disease){
        // if an animal is infected, it may die. Otherwise assume it gets immuntity from that disease.
        if(getIsInfected() && !getIsImmuned()){
            if(Randomizer.getRandom().nextDouble() <= disease.MORTALITY_RATE  ){
                setDead();
                populationDieOfDisease++;
                return true;
            }
        }
        return false;
    }


}

import java.util.Random;
import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;
import java.awt.Color;

/**
 * A simple predator-prey simulator, based on a rectangular field
 * containing Seaweed, Salmon, Cod, Shark, Whale, and also the elmement of disease and weather
 *
 * @version 2022/03/02
 */
public class Simulator
{
    // Constants representing configuration information for the simulation.
    // The default width for the grid.
    private static final int DEFAULT_WIDTH = 120;
    // The default depth of the grid.
    private static final int DEFAULT_DEPTH = 80;

    // The probability that a fox will be created in any given grid position.
    private static final double SALMON_CREATION_PROBABILITY = 0.08;
    // The probability that a rabbit will be created in any given grid position.
    private static final double COD_CREATION_PROBABILITY = 0.08;  
    // The probability that a seaweed will be created in any given grid position.
    private static final double SEAWEED_CREATION_PROBABILITY = 0.03;
    // The probability that a shark will be created in any given grid position.
    private static final double SHARK_CREATION_PROBABILITY = 0.04;
    // The probability that a whale will be created in any given grid position.
    private static final double WHALE_CREATION_PROBABILITY = 0.03;

    // The probability that a storm may occur.
    private static final double STORM_HAPPEN_PROBABILITY = 0.14; 
    // The probability that the disease may occur.
    private static final double DISEASE_PROBABILITY = 0.1;


    // List of creatures in the field.
    private List<Creature> creatures;
    // The current state of the field.
    private Field field;
    // The current step of the simulation.
    private int step;
    // A graphical view of the simulation.
    private SimulatorView view;
    private Disease disease;
    private Weather weather;


    // The inital level of dissolved oxygen in the water. 
    private double oxygenLevel; 

    /**
     * Construct a simulation field with default size.
     */
    public Simulator()
    {
        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
    }

    /**
     * Create a simulation field with the given size.
     * @param depth Depth of the field. Must be greater than zero.
     * @param width Width of the field. Must be greater than zero.
     */
    public Simulator(int depth, int width)
    {
        if(width <= 0 || depth <= 0) {
            System.out.println("The dimensions must be greater than zero.");
            System.out.println("Using default values.");
            depth = DEFAULT_DEPTH;
            width = DEFAULT_WIDTH;
        }

        creatures = new ArrayList<>();

        field = new Field(depth, width);
        weather = new Weather(field);
        disease = new Disease();

        oxygenLevel = 1;


        // Create a view of the state of each location in the field.
        view = new SimulatorView(depth, width);

        view.setColor(Cod.class, Color.ORANGE);
        view.setColor(Salmon.class, Color.YELLOW);
        view.setColor(Seaweed.class, Color.RED);
        view.setColor(Shark.class, Color.BLACK);
        view.setColor(Whale.class, Color.PINK);
        view.setColor(Weather.class,Color.BLUE);

        // Setup a valid starting point.
        reset();
    }

    /**
     * Run the simulation from its current state for a reasonably long period,
     * (1000 steps).
     */
    public void runLongSimulation()
    {
        simulate(1000);
    }

    /**
     * Run the simulation from its current state for the given number of steps.
     * Stop before the given number of steps if it ceases to be viable.
     * @param numSteps The number of steps to run for.
     */
    public void simulate(int numSteps)
    {
        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
            simulateOneStep();
            delay(60);   // uncomment this to run more slowly
        }
    }

    /**
     * Run the simulation from its current state for a single step.
     * 
     * Iterate over the whole field updating the state of each
     * creaturesÃ¯Â¼Ârecord the total amount of oxygen that is consumed or produced 
     * by specific species in each step, Storms have a certain probability of occurring�, 
     * update the oxygen level, and identify if the disease is stops.
     */
    public void simulateOneStep()
    {
        step++;

        double totalOxygenInvolved= 0; //oxygen that is generated or consumed in total for this step

        disease.creationSourceOfInfection(creatures, step);

        // Provide space for newborn animals.
        List<Creature> newCreatures = new ArrayList<>();        
        // Let all creatures act.
        for(Iterator<Creature> it = creatures.iterator(); it.hasNext(); ) {
            Creature creature = it.next();
            totalOxygenInvolved += creature.act(newCreatures, timeOfDay(), oxygenLevel, disease, step);
            if(!creature.isAlive()) {
                it.remove();
            }
        }

        if(Randomizer.getRandom().nextDouble() <= STORM_HAPPEN_PROBABILITY) {
            weather.underwaterStorm(3); //  generate the storm at a random location.
            weather.setStormStart(true);
        } else {
            weather.setStormStart(false);
        }        

        // calculate the oxygen left
        oxygenLevel += totalOxygenInvolved;

        // identify if disease stops
        if(disease.getIsSpread()){
            disease.setIsSpread(identifyIfDiseaseStops());
        }

        // Add the newly born creatures to the main lists.
        creatures.addAll(newCreatures);
        view.showStatus(step, field, timeOfDay(), weather, oxygenLevel);
    }

    /**
     * Reset the simulation to a starting position.
     */
    public void reset()
    {
        step = 0;
        creatures.clear();
        populate();
        oxygenLevel = 1;
        Animal.populationDieOfDisease = 0;

        // Show the starting state in the view.
        view.showStatus(step, field, timeOfDay(), weather, oxygenLevel);
    }

    /**
     * Randomly populate the field with Salmon, Seaweed, Shark and Whale.
     * notice if and else if is based on the creation probability of a creature in an ascending order
     */
    private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= SALMON_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Salmon salmon = new Salmon(true, field, location);
                    creatures.add(salmon);
                }
                else if(rand.nextDouble() <= COD_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Cod cod = new Cod(true, field, location);
                    creatures.add(cod);
                }
                else if(rand.nextDouble() <= SEAWEED_CREATION_PROBABILITY){
                    Location location = new Location (row, col);
                    Seaweed seaweed = new Seaweed(true, field, location);
                    creatures.add(seaweed);
                }else if(rand.nextDouble() <= SHARK_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Shark shark = new Shark(true, field, location);
                    creatures.add(shark);
                }else if(rand.nextDouble() <= WHALE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Whale whale = new Whale(true, field, location);
                    creatures.add(whale);
                }
                // else leave the location empty.
            }
        }
    }

    /**
     *  Pause for a given time.
     *  @param millisec  The time to pause for, in milliseconds
     */
    private void delay(int millisec)
    {
        try {
            Thread.sleep(millisec);
        }
        catch (InterruptedException ie) {
            // wake up
        }
    }

    /**
     * 5 steps is considered as a day time followed by 5 steps considered as a night.
     * 
     * @return true If currently step is day time false if it is night time.
     */
    public boolean timeOfDay(){
        return (step % 10) < 5;
    }

    /**
     *  If all animals infected die or all animals get immunity, the disease stops.
     *  Only animal can be infected.
     */
    public boolean identifyIfDiseaseStops(){

        List<Creature> newCreatures = new ArrayList<>();   

        boolean existDisease = true;

        for(Iterator<Creature> it = creatures.iterator(); it.hasNext(); ) {
            Creature creature = it.next();
            if(creature instanceof Animal){
                Animal ani = (Animal)creature;
                // if the animal is not infected or is immuned
                if(!ani.getIsInfected() || ani.getIsImmuned()){  
                    existDisease = false;
                }

                else{
                    existDisease = true;
                }
            }
        }

        return existDisease;
    }
}

