 11	 */
 12	public class Salmon extends Animal
 13	{
 14	    // Characteristics shared by all salmons (class variables).
 15	
 16	    // The age at which a salmon can start to breed.
 17	    private static final int BREEDING_AGE = 4;
 18	    // The age to which a salmon can live.
 19	    private static final int MAX_AGE = 50;
 20	    // The likelihood of a salmon breeding.
 21	    private static final double BREEDING_PROBABILITY = 0.3;
 22	    // The maximum number of births.
 23	    private static final int MAX_LITTER_SIZE = 15;
 24	
 25	    // The food value of a single salmon. In effect, this is the
 26	    // number of steps a fox can go before it has to eat again.
 27	    private static final int SEAWEED_FOOD_VALUE = 13;
 28	
 29	    // A shared random number generator to control breeding.
 30	    private static final Random rand = Randomizer.getRandom();
 31	
 32	    // Individual characteristics (instance fields).
 33	
 34	    // The salmon's age.
 35	    private int age;
 36	
 37	    // The salmon's food level
 38	    private int foodLevel;
 39	
 40	
 41	    /**
 42	     * Create a new salmon. A salmon may be created with age
 43	     * zero (a new born) or with a random age.
 44	     * 
 45	     * @param randomAge If true, the salmon will have a random age.
 46	     * @param field The field currently occupied.
 47	     * @param location The location within the field.
 48	     */
 49	    public Salmon(boolean randomAge, Field field, Location location)
 50	    {
 51	        super(field, location);
 52	        if(randomAge) {
 53	            age = rand.nextInt(MAX_AGE);
 54	            foodLevel = rand.nextInt(SEAWEED_FOOD_VALUE);
 55	        }
 56	        else {
 57	            age = 0;
 58	            foodLevel = SEAWEED_FOOD_VALUE;
 59	        }
 60	    }
 61	
 62	    /**
 63	     * This is what the salmon does most of the time - it runs 
 64	     * around. Sometimes it will breed or die of old age.
 65	     * 
 66	     * @param newSalmons A list to return newly born salmons.
 67	     * @param atDayTime true if current step is daytime false otherwise.
 68	     * @param oxygenLevel The inital level of dissolved oxygen in the water.
 69	     * @param disease The disease may happened during simulation.  
 70	     * @param step current step.
 71	     * 
 72	     * @return the oxygen level the species produced or consumed after action.
 73	     */
 74	    protected void incrementAge()
 75	    {
 76	        age++;
 77	        if(age > MAX_AGE) {
 78	            setDead();
 79	        }
 80	    }
 81	
 82	    /**
 83	     * Make this salmon more hungry. This could result in the salmon's death.
 84	     */
 85	    protected void incrementHunger()
 86	    {
 87	        foodLevel--;
 88	        if(foodLevel <= 0) {
 89	            setDead();
 90	        }
 91	    }
