 93	    /**
 94	     * Look for seaweed adjacent to the current location.
 95	     * Only the first live seaweed is eaten, if the nearby animal is 
 96	     * infected, then this animal also may be infected.
 97	     * @param disease disease.
 98	     * @param step int current step.
 99	     * @return Where food was found, or null if it wasn't.
100	     */
101	    public Location search(Disease disease, int step){
102	        return findFood(disease, step, 1, SEAWEED_FOOD_VALUE, Seaweed.class);
103	    }
104	    /**
105	     * Check whether or not this salmon is to give birth at this step.
106	     * New births will be made into free adjacent locations.
107	     * @param newsalmons A list to return newly born salmons.
108	     */
109	    protected void giveBirth(List<Creature> newSalmons)
110	    {
111	        // New salmons are born into adjacent locations.
112	        // Get a list of adjacent free locations.
113	        Field field = getField();
114	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
115	        int births = breed();
116	        for(int b = 0; b < births && free.size() > 0; b++) {
117	            Location loc = free.remove(0);
118	            Salmon young = new Salmon(false, field, loc);
119	            newSalmons.add(young);
120	        }
121	    }
