123	    /**
124	     * Generate a number representing the number of births,
125	     * if it can breed.
126	     * @return The number of births (may be zero).
127	     */
128	    private int breed()
129	    {
130	        int births = 0;
131	        if(canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY) {
132	            births = rand.nextInt(MAX_LITTER_SIZE) + 1;
133	        }
134	        return births;
135	    }
136	
137	    /**
138	     * A salmon can breed if it has reached the breeding age and has countered the salmon of opposite sex.
139	     * @return true if the salmon can breed, false otherwise.
140	     */
141	    private boolean canBreed()
142	    {
143	        return age >= BREEDING_AGE && encounterWithDiffSex();
144	    }
