125	        stepLabel.setText(STEP_PREFIX + step);
126	        infoLabel.setText("It is: " + (timeOfDay? "daytime": "night ") 
127	                            + "        Oxygen Level: " + (int)(oxygenLevel * 100) + "%"
128	                            + "        Storm: " + (weather.getStormStart()? "exists": "subsides"));
129	        diseaseLabel.setText(POPULATION_DIE_OF_DISEASE_PREFIX + Animal.populationDieOfDisease);
130	        stats.reset();
131	        
132	        fieldView.preparePaint();
133	
134	        for(int row = 0; row < field.getDepth(); row++) {
135	            for(int col = 0; col < field.getWidth(); col++) {
136	                Creature creature = field.getCreatureAt(row, col);
137	                if(creature != null && weather.getStormStart() == false) {
138	                    stats.incrementCount(creature.getClass());
139	                    if(creature instanceof Animal){
140	                     Animal ani = (Animal)creature;
141	                        if(ani.getIsInfected() && !ani.getIsImmuned())
142	                            fieldView.drawMark(col, row, INFECTED_COLOR);
143	                        else 
144	                            fieldView.drawMark(col, row, getColor(creature.getClass()));
145	                    }
146	                    else
147	                        fieldView.drawMark(col, row, getColor(creature.getClass()));
148	                }
149	                else if(creature != null && weather.getStormStart() == true) {
150	                    stats.incrementCount(creature.getClass());
151	                    fieldView.drawMark(col, row, getColor(creature.getClass())); 
152	                    drawStormColor(field, weather);
153	                }
154	                else {
155	                    fieldView.drawMark(col, row, EMPTY_COLOR);
156	                }   
157	                    
158	            }
159	        }
160	                
161	            
162	        
163	        stats.countFinished();
164	        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
165	        fieldView.repaint();
166	    }
