177	    /**
178	     * Draw the colour of the storm, and the range of the storm is given by storm scope of 
179	     * the object of Weather class.
180	     * 
181	     * @param field The field where the weather might happen and to be displayed.
182	     * @param weather the object of Weather class
183	     */
184	    private void drawStormColor(Field field, Weather weather) {
185	        List<Location> stormLocation = field.adjacentLocationsIncludingSelf(weather.getRandomLocation(),weather.getStormScope());
186	        for(Location location : stormLocation) {
187	            fieldView.drawMark(location.getCol(),location.getRow(),getColor(Weather.class));
188	        }
189	        
190	    }
